        "domain"
    )

    abuseipdb, ip_details = abuse_results(
        ABUSEIPDB_RAW
    )

    risk_score = combine([
        wazuh,
        vt_hash,
        vt_domain,
        abuseipdb
    ])

    result = {
        "risk_score": risk_score,
        "risk_verdict": verdict(risk_score),
        "skip_llm_recommended": risk_score >= 80,
        "reason": None,

        "source_scores": {
            "wazuh": wazuh,
            "vt_hash": vt_hash,
            "vt_domain": vt_domain,
            "abuseipdb": abuseipdb
        },

        "ioc_details": (
            hash_details
            + domain_details
            + ip_details
        )
    }

    print(
        json.dumps(
            result,
            ensure_ascii=False
        )
    )

except Exception as e:

    print(
