import json

NORMALIZED_RAW = r'''$normalizer.message'''
DETERMINISTIC_RAW = r'''$ioc_enrichement_merge.message'''
LLM_RAW = r'''$llm-analysis_groq'''

IRIS_CUSTOMER_ID = 1


# ============================================================
# HELPERS
# ============================================================

def jload(v):
    if isinstance(v, (dict, list)):
        return v

    if not isinstance(v, str) or not v.strip() or v.strip().startswith("$"):
        return None

    try:
        x = json.loads(v)

        if isinstance(x, str) and x.strip().startswith(("{", "[")):
            x = json.loads(x)

        return x

    except:
        return None


def num(v):
    try:
        return max(
            0,
            min(100, float(v))
        )
    except:
        return None


def dct(v):
    return v if isinstance(v, dict) else {}


def lst(v):
    return v if isinstance(v, list) else []


# ============================================================
# INPUTS
# ============================================================

def parse_normalized():
    x = jload(NORMALIZED_RAW)

    if not isinstance(x, dict):
        return {}

    return (
        x["message"]
        if isinstance(x.get("message"), dict)
        else x
    )


def parse_deterministic():
    x = jload(DETERMINISTIC_RAW)

    if not isinstance(x, dict):
        return None

    if (
        "risk_score" not in x
        and isinstance(x.get("message"), dict)
    ):
        x = x["message"]

    score = num(
        x.get("risk_score")
    )

    if score is None:
        return None

    return {
        "score": score,

        "risk_verdict":
            x.get("risk_verdict")
            or x.get("verdict")
            or x.get("risk_level"),

        "skip_llm_recommended":
            x.get("skip_llm_recommended"),

        "source_scores":
            x.get("source_scores")
            or x.get("scores"),

        "ioc_details":
            lst(x.get("ioc_details"))
    }


def parse_llm():
    x = jload(LLM_RAW)

    if x is None:
        return None

    if isinstance(x, list):
        x = next(
            (
                i for i in x
                if isinstance(i, dict)
                and i.get("status") == 200
            ),
            x[0] if x else None
        )

    if not isinstance(x, dict):
        return None

    body = x.get("body")

    if body is not None:
        body = (
            jload(body)
            if isinstance(body, str)
            else body
        )

        if isinstance(body, dict):
            x = body

    choices = x.get("choices")

    if isinstance(choices, list) and choices:

        content = dct(
            choices[0].get("message")
        ).get("content")

        parsed = jload(content)

        if isinstance(parsed, dict):
            x = parsed

    score = num(
        x.get("context_risk_score")
    )

    if score is None:
        return None

    return {
        "score": score,
        "context_verdict": x.get("context_verdict"),
        "confidence": num(x.get("confidence")),
        "summary": x.get("summary"),
        "attack_chain": x.get("attack_chain"),
        "key_evidence": lst(x.get("key_evidence")),
        "benign_context": lst(x.get("benign_context")),
        "uncertainties": lst(x.get("uncertainties")),
        "related_mitre": lst(x.get("related_mitre")),
        "recommended_action": x.get("recommended_action")
    }


# ============================================================
# RISK
# ============================================================

def wazuh_fallback(level):
    try:
        level = int(level)
    except:
        return None

    if level <= 4:
        return 10

    if level <= 7:
        return 20

    if level <= 9:
        return 30

    if level <= 11:
        return 40

    if level <= 13:
        return 50

    if level == 14:
        return 60

    return 70


def risk_level(score):
    if score >= 80:
        return "CRITICAL"

    if score >= 60:
        return "HIGH"

    if score >= 35:
        return "MEDIUM"

    return "LOW"


def action(score):
    if score >= 60:
        return "escalate"

    if score >= 35:
        return "review"

    if score >= 20:
        return "monitor"

    return "close"


def combine(det, ctx):
    if det is None and ctx is None:
        return None, 0, None

    if ctx is None:
        return det, 0, "deterministic"

    if det is None:
        return ctx, 0, "behavioral_context"

    if det >= ctx:
        high = det
        low = ctx
        source = "deterministic"

    else:
        high = ctx
        low = det
        source = "behavioral_context"

    boost = (
        low * 0.15
        if low >= 35
        else 0
    )

    return (
        min(100, high + boost),
        boost,
        source
    )


# ============================================================
# IRIS
# ============================================================

def iris_severity(level):
    return {
        "LOW": 4,
        "MEDIUM": 1,
        "HIGH": 5,
        "CRITICAL": 6
    }.get(level, 2)


def iris_priority(score):
    if score >= 80:
        return "urgent"

    if score >= 60:
        return "high"

    if score >= 35:
        return "normal"

    return "low"


def build_title(n, severity):
    trigger = dct(
        n.get("trigger")
    )

    agent = dct(
        n.get("agent")
    )

    desc = (
        trigger.get("rule_description")
        or n.get("alert_type")
        or "Security Alert"
    )

    host = (
        agent.get("name")
        or agent.get("id")
        or "unknown-endpoint"
    )

    title = (
        f"[{severity}] "
        f"{desc} - {host}"
    )

    return (
        title[:177] + "..."
        if len(title) > 180
        else title
    )


