IOC_TYPES = {
    "domain": 20,
    "ip": 76,
    "sha256": 113,
    "url": 141
}


def ioc_description(e):
    if not e:
        return (
            "IOC extracted automatically "
            "from Wazuh / Shuffle."
        )

    parts = [
        "IOC extracted automatically from Wazuh / Shuffle."
    ]

    fields = [
        ("Provider", "provider", ""),
        ("Verdict", "verdict", ""),
        ("IOC Risk Score", "score", "/100"),
        ("Malicious detections", "malicious", ""),
        ("Suspicious detections", "suspicious", ""),
        ("Harmless detections", "harmless", ""),
        ("Undetected vendors", "undetected", ""),
        ("AbuseIPDB confidence", "abuse_confidence", "%"),
        ("AbuseIPDB reports", "total_reports", ""),
        ("Country", "country", "")
    ]

    for label, key, suffix in fields:

        value = e.get(key)

        if value is not None:
            parts.append(
                f"{label}: {value}{suffix}"
            )

    return " | ".join(parts)


def build_iocs(obs, details):
    sources = [
        ("sha256", "sha256"),
        ("url", "urls"),
        ("domain", "domains"),
        ("ip", "public_ips")
    ]

    detail_map = {}

    for item in details:

        if not isinstance(item, dict):
            continue

        typ = str(
            item.get("type") or ""
        )

        value = str(
            item.get("value") or ""
        )

        if typ and value:
            detail_map[
                (typ, value)
            ] = item

    out = []
    seen = set()

    for typ, field in sources:

        for value in lst(
            obs.get(field)
        ):

            if not value:
                continue

            key = (
                typ,
                str(value)
            )

            if key in seen:
                continue

            seen.add(key)

            enrichment = detail_map.get(
                key
            )

            out.append({
                "type": typ,
                "ioc_type_id": IOC_TYPES[typ],
                "value": value,
                "enrichment": enrichment,
                "description":
                    ioc_description(enrichment)
            })

    return out


# ============================================================
# LLM NOTE
# ============================================================

def build_llm_note(llm, trigger):
    if not llm:
        return None

    confidence = (
        int(round(llm["confidence"]))
        if llm.get("confidence") is not None
        else None
    )

    confidence_text = (
        f"{confidence}%"
        if confidence is not None
        else "N/A"
    )

    lines = [
        "Automated Behavioral Context Analysis",
        "",
        f"Wazuh Trigger: {trigger.get('rule_description') or 'N/A'}",
        f"Wazuh Rule: {trigger.get('rule_id') or 'N/A'}",
        f"Wazuh Level: {trigger.get('rule_level') if trigger.get('rule_level') is not None else 'N/A'}",
        "",
        f"Context Risk Score: {int(round(llm['score']))}/100",
        f"Context Verdict: {llm.get('context_verdict') or 'N/A'}",
        f"Confidence: {confidence_text}",
        f"Attack Chain: {llm.get('attack_chain') or 'N/A'}",
        f"Recommended Action: {llm.get('recommended_action') or 'N/A'}",
        "",
        "Context Summary:",
        str(
            llm.get("summary")
            or "N/A"
        )
    ]

    evidence = lst(
        llm.get("key_evidence")
    )

    if evidence:

        lines += [
            "",
            "Key Evidence:"
        ]

        for item in evidence:

            if isinstance(item, dict):

                lines.append(
                    "- [{}] {}".format(
                        str(
                            item.get(
                                "severity",
                                "unknown"
                            )
                        ).upper(),

                        item.get(
                            "finding",
                            ""
                        )
                    )
                )

            else:
                lines.append(
                    f"- {item}"
                )

    benign = lst(
        llm.get("benign_context")
    )

    if benign:

        lines += [
            "",
            "Benign Context:"
        ]

        for item in benign:
            lines.append(
                f"- {item}"
            )

    uncertainties = lst(
        llm.get("uncertainties")
    )

    if uncertainties:

        lines += [
            "",
            "Uncertainties:"
        ]

        for item in uncertainties:
            lines.append(
                f"- {item}"
            )

    mitre = lst(
        llm.get("related_mitre")
    )

    if mitre:

        lines += [
            "",
            "Related MITRE: "
            + ", ".join(
                str(x)
                for x in mitre
            )
        ]

    return "\n".join(lines)


# ============================================================
# MAIN
# ============================================================

def main():
    warnings = []

    n = parse_normalized()
    det = parse_deterministic()
    llm = parse_llm()

    trigger = dct(
        n.get("trigger")
    )

    agent = dct(
        n.get("agent")
    )

    obs = dct(
        n.get("observables")
    )

    det_score = (
        det["score"]
        if det
        else None
    )

    ctx_score = (
        llm["score"]
        if llm
        else None
    )

    final, boost, dominant = combine(
        det_score,
        ctx_score
    )

    if (
        det_score is not None
        and ctx_score is not None
    ):
        mode = "combined"

    elif det_score is not None:
        mode = "deterministic_only"

    elif ctx_score is not None:
        mode = "behavioral_only"

    else:
        mode = "wazuh_fallback"

    if final is None:

        final = wazuh_fallback(
            trigger.get("rule_level")
        )

        dominant = "wazuh_fallback"

        if final is None:

            return {
                "decision_status": "error",
                "create_iris_case": False,
                "reason": "No usable risk source"
            }

        warnings.append(
            "deterministic_and_llm_scores_missing"
        )

    final = int(
        round(final)
    )

    severity = risk_level(
        final
    )

    create_case = (
        final >= 35
    )

    iocs = build_iocs(
        obs,
        (
            det.get("ioc_details")
            if det
            else []
        )
    )

    if (
        dominant == "behavioral_context"
        and llm
    ):
        final_verdict = llm.get(
            "context_verdict"
        )

    elif (
        dominant == "deterministic"
        and det
    ):
        final_verdict = det.get(
            "risk_verdict"
        )

    else:
        final_verdict = None

    final_verdict = (
        final_verdict
        or (llm or {}).get("context_verdict")
        or (det or {}).get("risk_verdict")
        or severity.lower()
    )

    return {
        "decision_status": "ok",
        "decision_mode": mode,

        "scores": {
            "deterministic":
                int(round(det_score))
                if det_score is not None
                else None,

            "behavioral_context":
                int(round(ctx_score))
                if ctx_score is not None
                else None,

            "support_boost":
                round(boost, 2),

            "final":
                final
        },

        "dominant_source":
            dominant,

        "final_risk_score":
            final,

        "final_risk_level":
            severity,

        "final_verdict":
            final_verdict,

        "final_action":
            action(final),

        "create_iris_case":
            create_case,

        "iris": {
            "customer_id":
                IRIS_CUSTOMER_ID,

            "severity":
                severity,

            "severity_id":
                iris_severity(severity),

            "priority":
                iris_priority(final),

            "title":
                build_title(
                    n,
                    severity
                ),

            "ioc_targets":
                iocs,

            "llm_note_title":
                "Automated Behavioral Context Analysis",

            "llm_note_content":
                build_llm_note(
                    llm,
                    trigger
                ),

            "routing": {
                "create_case":
                    create_case,

                "set_severity":
                    create_case,

                "add_ioc":
                    bool(
                        create_case
                        and iocs
                    ),

                "add_llm_note":
                    bool(
                        create_case
                        and llm
                    )
            }
        },

        "alert": {
            "alert_id":
                trigger.get("alert_id"),

            "alert_type":
                n.get("alert_type"),

            "timestamp":
