import json
import urllib.request
import urllib.error
import ssl


# ============================================================
# SHUFFLE INPUTS
# ============================================================

FINAL_DECISION_RAW = r'''$final_decision.message'''

IRIS_CREATE_CASE_RAW = r'''$iris_create_case'''

IRIS_URL = r'''$iris_url'''

IRIS_API_KEY = r'''$iris_api_key'''


# ============================================================
# SETTINGS
# ============================================================

VERIFY_TLS = False

IOC_TLP_ID = 2


# ============================================================
# IRIS IOC TYPE IDS
# ============================================================

IOC_TYPE_IDS = {
    "domain": 20,
    "ip": 76,       # ip-any
    "sha256": 113,
    "url": 141
}


# ============================================================
# HELPERS
# ============================================================

def jload(value):
    if isinstance(value, (dict, list)):
        return value

    if not isinstance(value, str):
        return None

    value = value.strip()

    if not value or value.startswith("$"):
        return None

    try:
        return json.loads(value)
    except Exception:
        return None


def sslctx():
    if VERIFY_TLS:
        return ssl.create_default_context()

    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE

    return ctx


def extract_case_id(raw):
    data = jload(raw)

    if not isinstance(data, dict):
        return None

    # Expected HTTP output:
    # {
    #   "status": 200,
    #   "body": {
    #       "data": {
    #           "case_id": 6
    #       }
    #   }
    # }

    body = data.get("body")

    if isinstance(body, str):
        body = jload(body)

    if not isinstance(body, dict):
        return None

    case_data = body.get("data")

    if not isinstance(case_data, dict):
        return None

    return case_data.get("case_id")


def get_ioc_targets(raw):
    data = jload(raw)

    if not isinstance(data, dict):
        return []

    iris = data.get("iris") or {}

    targets = iris.get("ioc_targets") or []

    if not isinstance(targets, list):
        return []

    return targets


# ============================================================
# ADD ONE IOC
# ============================================================

def add_ioc(case_id, ioc_type, value):
    type_id = IOC_TYPE_IDS.get(
        str(ioc_type).lower()
    )

    if type_id is None:
        return {
            "success": False,
            "type": ioc_type,
            "value": value,
            "reason": "unsupported_ioc_type"
        }

    if not value:
        return {
            "success": False,
            "type": ioc_type,
            "value": value,
            "reason": "empty_ioc_value"
        }

    url = (
        IRIS_URL.rstrip("/")
        + "/case/ioc/add?cid="
        + str(case_id)
    )

    payload = {
        "ioc_type_id": type_id,

        "ioc_tlp_id": IOC_TLP_ID,

        "ioc_value": value,

        "ioc_description":
            "IOC extracted automatically from Wazuh and Shuffle.",

        "ioc_tags":
            "wazuh,shuffle,automated",

        "custom_attributes": {}
    }

    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        method="POST",
        headers={
            "Authorization":
                "Bearer " + IRIS_API_KEY,

            "Content-Type":
                "application/json"
        }
    )

    try:
        with urllib.request.urlopen(
            req,
            context=sslctx(),
            timeout=15
        ) as response:

            body = json.loads(
                response.read().decode()
            )

            return {
                "success": True,
                "type": ioc_type,
                "type_id": type_id,
                "value": value,
                "http_status": response.status,
                "iris_response": body
            }

    except urllib.error.HTTPError as e:

        detail = e.read().decode(
            "utf-8",
            errors="replace"
        )

        try:
            detail = json.loads(detail)
        except Exception:
            pass

        return {
            "success": False,
            "type": ioc_type,
            "type_id": type_id,
            "value": value,
            "http_status": e.code,
            "iris_response": detail
        }

    except Exception as e:

        return {
            "success": False,
            "type": ioc_type,
            "type_id": type_id,
            "value": value,
            "reason": type(e).__name__,
            "detail": str(e)
        }


# ============================================================
# MAIN
# ============================================================

try:
    case_id = extract_case_id(
        IRIS_CREATE_CASE_RAW
    )

    if not case_id:
        raise ValueError(
            "Unable to extract IRIS case_id"
        )

    targets = get_ioc_targets(
        FINAL_DECISION_RAW
    )

    if not targets:
        print(
            json.dumps(
                {
                    "status": "skipped",
                    "reason": "no_iocs",
                    "case_id": case_id,
                    "added": 0,
                    "failed": 0,
                    "results": []
                },
                ensure_ascii=False
            )
        )

    else:

        # --------------------------------------------
        # Deduplicate before sending
        # --------------------------------------------

        seen = set()
        unique_targets = []

        for item in targets:

            if not isinstance(item, dict):
                continue

            ioc_type = item.get("type")
            value = item.get("value")

            key = (
                str(ioc_type).lower(),
                str(value)
            )

            if key in seen:
                continue

            seen.add(key)

            unique_targets.append({
                "type": ioc_type,
                "value": value
            })


        # --------------------------------------------
        # Add every IOC
        # --------------------------------------------

        results = []

        for item in unique_targets:

            result = add_ioc(
                case_id,
                item.get("type"),
                item.get("value")
            )

            results.append(result)


        added = sum(
            1
            for r in results
            if r.get("success") is True
        )

        failed = sum(
            1
            for r in results
            if r.get("success") is not True
        )


        print(
            json.dumps(
                {
                    "status": (
                        "ok"
                        if failed == 0
                        else "partial"
                    ),

                    "case_id": case_id,

                    "requested": len(
                        unique_targets
                    ),

                    "added": added,

                    "failed": failed,

                    "results": results
                },
                ensure_ascii=False
            )
        )


except Exception as e:

    print(
        json.dumps(
            {
                "status": "error",
                "reason": type(e).__name__,
                "detail": str(e)
            },
            ensure_ascii=False
        )
    )

import json
import ssl
import urllib.request
import urllib.error


FINAL_RAW = r'''$final_decision.message'''
CASE_RAW = r'''$iris_create_case'''

IRIS_URL = r'''$iris_url'''
IRIS_API_KEY = r'''$iris_api_key'''

VERIFY_TLS = False


# ============================================================
# HELPERS
# ============================================================

def jload(v):
    if isinstance(v, (dict, list)):
        return v

    if not isinstance(v, str):
        return None

    try:
        return json.loads(v)
    except:
        return None


def ssl_context():
    ctx = ssl.create_default_context()

    if not VERIFY_TLS:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE

    return ctx


def post(path, payload):
    url = (
        IRIS_URL.rstrip("/")
        + path
    )

    req = urllib.request.Request(
        url,
        method="POST",
        data=json.dumps(
            payload
        ).encode("utf-8"),
        headers={
            "Authorization":
                "Bearer " + IRIS_API_KEY,

            "Content-Type":
                "application/json"
        }
    )

    try:
        with urllib.request.urlopen(
            req,
            context=ssl_context(),
            timeout=15
        ) as response:

            raw = response.read().decode(
                "utf-8"
            )

            return (
                json.loads(raw)
                if raw
                else {}
            )

    except urllib.error.HTTPError as e:

        raw = e.read().decode(
            "utf-8",
            errors="replace"
        )

        raise RuntimeError(
            f"HTTP {e.code}: {raw}"
        )


def get_case_id():
    x = jload(CASE_RAW)

    if not isinstance(x, dict):
        return None

    body = x.get(
        "body",
        x
    )

    if isinstance(body, str):
        body = jload(body)

    if not isinstance(body, dict):
        return None

    data = body.get(
        "data"
    ) or {}

    return data.get(
        "case_id"
    )


def get_note_data():
    x = jload(FINAL_RAW)

    if not isinstance(x, dict):
        return None, None

    iris = (
        x.get("iris")
        or {}
    )

    return (
        iris.get(
            "llm_note_title"
        ),
        iris.get(
            "llm_note_content"
        )
    )


# ============================================================
# MAIN
# ============================================================

try:
    cid = get_case_id()

    if not cid:
        raise ValueError(
            "Missing IRIS case_id"
        )

    title, content = get_note_data()

    if not content:

        print(
            json.dumps(
                {
                    "status": "skipped",
                    "case_id": cid,
                    "reason": "No LLM note content"
                },
                ensure_ascii=False
            )
        )

    else:

        # ----------------------------------------------------
        # Create folder for automated analysis
        # ----------------------------------------------------

        directory_response = post(
            (
                "/case/notes/directories/add"
                "?cid="
                + str(cid)
            ),
            {
                "name":
                    "Automated Analysis",

                "parent_id":
                    None
            }
        )

        directory_data = (
            directory_response.get(
                "data"
            )
            or {}
        )

        # IRIS legacy endpoint may return group_id,
        # while newer directory responses may return id.
        directory_id = (
            directory_data.get("id")
            or directory_data.get("directory_id")
            or directory_data.get("group_id")
        )

        if not directory_id:

            raise ValueError(
                "IRIS did not return a directory ID: "
                + json.dumps(
                    directory_response,
                    ensure_ascii=False
                )
            )


        # ----------------------------------------------------
        # Add LLM analysis note
        # ----------------------------------------------------

        note_response = post(
            (
                "/case/notes/add"
                "?cid="
                + str(cid)
            ),
            {
                "note_title":
                    title
                    or "Automated Behavioral Context Analysis",

                "note_content":
                    content,

                "directory_id":
                    directory_id
            }
        )


        print(
            json.dumps(
                {
                    "status": "ok",
                    "case_id": cid,
                    "directory_id": directory_id,
                    "note_id":
                        (
                            note_response
                            .get("data", {})
                            .get("note_id")
                        ),
                    "note_response":
                        note_response
                },
                ensure_ascii=False
            )
        )


except Exception as e:

    print(
        json.dumps(
            {
                "status": "error",
                "reason": type(e).__name__,
                "detail": str(e)
            },
            ensure_ascii=False
        )
    )
